using Microsoft.EntityFrameworkCore;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.Authentication;
using System.Text;
using System.Text.RegularExpressions;
var builder=WebApplication.CreateBuilder(args); builder.WebHost.UseUrls("http://0.0.0.0:5080"); builder.Services.AddDbContext<AppDb>(o=>o.UseSqlite("Data Source=app.db")); builder.Services.AddAuthentication(CookieAuthenticationDefaults.AuthenticationScheme).AddCookie(o=>{o.LoginPath="/api/auth/me";o.Cookie.HttpOnly=true;}); builder.Services.AddAuthorization(); var app=builder.Build(); using(var s=app.Services.CreateScope()){var d=s.ServiceProvider.GetRequiredService<AppDb>();d.Database.EnsureCreated();if(!d.Users.Any())Seed(d);} app.UseAuthentication();app.UseAuthorization();
static User? Cur(HttpContext c,AppDb d)=>int.TryParse(c.User.FindFirst("id")?.Value,out var id)?d.Users.Find(id):null; static bool Admin(User? u)=>u?.Role=="管理者"; static string Day()=>TimeZoneInfo.ConvertTimeBySystemTimeZoneId(DateTime.UtcNow,"Tokyo Standard Time").ToString("yyyyMMdd"); static void Mail(string to,string subject,string body){Directory.CreateDirectory("maildrop");File.WriteAllText(Path.Combine("maildrop",Guid.NewGuid()+".json"),System.Text.Json.JsonSerializer.Serialize(new{to,subject,body,sentAt=DateTimeOffset.UtcNow.ToString("O")}));}
app.MapPost("/api/auth/login",async(Login x,HttpContext c,AppDb d)=>{var u=await d.Users.SingleOrDefaultAsync(a=>a.Email==x.Email);if(u==null||!u.Active||u.Locked)return Results.BadRequest(new{message=u?.Locked==true?"アカウントがロックされています。管理者にお問い合わせください":u?.Active==false?"このアカウントは無効です":"メールアドレスまたはパスワードが正しくありません"});if(!BCrypt.Net.BCrypt.Verify(x.Password,u.PasswordHash)){if(++u.Failures>=5)u.Locked=true;await d.SaveChangesAsync();return Results.BadRequest(new{message=u.Locked?"アカウントがロックされています。管理者にお問い合わせください":"メールアドレスまたはパスワードが正しくありません"});}u.Failures=0;await d.SaveChangesAsync();await c.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new System.Security.Claims.ClaimsPrincipal(new System.Security.Claims.ClaimsIdentity(new[]{new System.Security.Claims.Claim("id",u.Id.ToString())},CookieAuthenticationDefaults.AuthenticationScheme)));return Results.Ok(new{u.Id,u.Name,u.Email,u.Department,u.Role});}); app.MapPost("/api/auth/logout",async(HttpContext c)=>{await c.SignOutAsync();return Results.Ok();}); app.MapGet("/api/auth/me",(HttpContext c,AppDb d)=>{var u=Cur(c,d);return u==null?Results.Unauthorized():Results.Ok(new{u.Id,u.Name,u.Email,u.Department,u.Role});});
app.MapPost("/api/dev/reset",(HttpContext c,AppDb d)=>{if(!app.Environment.IsDevelopment())return Results.NotFound();d.Database.EnsureDeleted();d.Database.EnsureCreated();Seed(d);if(Directory.Exists("maildrop"))Directory.Delete("maildrop",true);return Results.Ok(new{message="初期化しました"});});
app.MapPost("/api/users/register",(Register x,AppDb d)=>{if(string.IsNullOrWhiteSpace(x.Name))return Results.BadRequest(new{message="氏名を入力してください"});if(!x.Email.Contains('@'))return Results.BadRequest(new{message="有効なメールアドレスを入力してください"});if(x.Password.Length<8||!Regex.IsMatch(x.Password,"[A-Za-z]")||!Regex.IsMatch(x.Password,"[0-9]"))return Results.BadRequest(new{message="パスワードは8文字以上で英字と数字を含めてください"});if(x.Password!=x.Confirm)return Results.BadRequest(new{message="パスワードが一致しません"});if(d.Users.Any(u=>u.Email==x.Email))return Results.BadRequest(new{message="このメールアドレスは既に登録されています"});var u=new User{Name=x.Name,Email=x.Email,Department=x.Department,Role=x.Role,PasswordHash=BCrypt.Net.BCrypt.HashPassword(x.Password),Active=true};d.Users.Add(u);d.SaveChanges();Mail(u.Email,"登録完了","アカウント登録が完了しました。");return Results.Ok(new{message="登録しました"});});
app.MapGet("/api/users",(HttpContext c,AppDb d)=>{var u=Cur(c,d);return !Admin(u)?Results.Json(new{message="ユーザー管理の権限がありません"},statusCode:403):Results.Ok(d.Users.Select(x=>new{x.Id,x.Name,x.Email,x.Department,x.Role,x.Active}));});
app.MapGet("/api/applications",(HttpContext c,AppDb d,string? q,string? status,string? type)=>{var u=Cur(c,d);if(u==null)return Results.Unauthorized();var z=d.Applications.Include(a=>a.Applicant).Include(a=>a.Approver).AsQueryable();if(!Admin(u))z=z.Where(a=>a.ApplicantId==u.Id||a.ApproverId==u.Id);if(!string.IsNullOrWhiteSpace(q))z=z.Where(a=>(a.Number??"").Contains(q)||a.Title.Contains(q));if(!string.IsNullOrWhiteSpace(status)&&status!="全て")z=z.Where(a=>a.Status==status);if(!string.IsNullOrWhiteSpace(type))z=z.Where(a=>a.Type==type);return Results.Ok(z.OrderByDescending(a=>a.ApplicationDate).Select(a=>new{a.Id,a.Number,a.Type,a.Title,a.Amount,a.Reason,a.ApplicationDate,a.Status,ApplicantName=a.Applicant!.Name,ApproverName=a.Approver==null?null:a.Approver.Name}));});
app.MapGet("/api/applications/{id}",(int id,HttpContext c,AppDb d)=>{var u=Cur(c,d);var a=d.Applications.Include(x=>x.Applicant).Include(x=>x.Approver).Include(x=>x.History).ThenInclude(h=>h.Actor).SingleOrDefault(x=>x.Id==id);if(u==null)return Results.Unauthorized();if(a==null)return Results.NotFound(new{message="指定された申請書が見つかりません"});if(!Admin(u)&&a.ApplicantId!=u.Id&&a.ApproverId!=u.Id)return Results.Json(new{message="この申請書を参照する権限がありません"},statusCode:403);return Results.Ok(new{a.Id,a.Number,a.Type,a.Title,a.Amount,a.Reason,a.ApplicationDate,a.Status,ApplicantName=a.Applicant!.Name,ApproverName=a.Approver?.Name,History=a.History.OrderBy(h=>h.At).Select(h=>new{h.At,h.Action,h.Comment,Actor=h.Actor!.Name,Role=h.Actor.Role})});});
app.MapPost("/api/applications",async(AppInput x,HttpContext c,AppDb d)=>{var u=Cur(c,d);if(u==null)return Results.Unauthorized();if(x.Submit&&(string.IsNullOrWhiteSpace(x.Title)||string.IsNullOrWhiteSpace(x.Reason)))return Results.BadRequest(new{message="必須項目を入力してください"});if(x.Amount<1||x.Amount>9999999)return Results.BadRequest(new{message="申請金額は1円以上9,999,999円以下で入力してください"});var a=new Application{ApplicantId=u.Id,Type=x.Type,Title=x.Title??"",Amount=x.Amount,Reason=x.Reason??"",ApplicationDate=x.ApplicationDate,Status=x.Submit?"承認待ち":"下書き"};if(x.Submit){var role=x.Amount>=1000000?"部長":"課長";var ap=await d.Users.FirstOrDefaultAsync(v=>v.Role==role&&v.Active);if(ap==null)return Results.BadRequest(new{message="対象の役職を持つユーザーが存在しません。管理者にお問い合わせください"});a.ApproverId=ap.Id;a.Number=$"REQ-{Day()}-{(d.Applications.Count()+1):D4}";}d.Applications.Add(a);d.SaveChanges();d.Histories.Add(new History{ApplicationId=a.Id,ActorId=u.Id,Action=x.Submit?"提出":"下書き保存",At=DateTime.UtcNow});d.SaveChanges();if(x.Submit){var ap=d.Users.Find(a.ApproverId);Mail(ap!.Email,$"【承認依頼】{a.Title}",$"申請番号: {a.Number}\nタイトル: {a.Title}\nステータス: 承認待ち\n申請詳細URL: /applications/{a.Id}");}return Results.Ok(a);});
app.MapPost("/api/applications/{id}/action",async(int id,ActionInput x,HttpContext c,AppDb d)=>{var u=Cur(c,d);var a=await d.Applications.Include(z=>z.Applicant).Include(z=>z.Approver).SingleOrDefaultAsync(z=>z.Id==id);if(u==null)return Results.Unauthorized();if(a==null)return Results.NotFound();if(x.Action=="approve"||x.Action=="reject"){if(a.ApproverId!=u.Id)return Results.Json(new{message="この申請書を操作する権限がありません"},statusCode:403);if(a.Status!="承認待ち")return Results.BadRequest(new{message="承認待ち状態の申請書のみ操作できます"});if(x.Action=="reject"&&string.IsNullOrWhiteSpace(x.Comment))return Results.BadRequest(new{message="差し戻し理由を入力してください"});a.Status=x.Action=="approve"?"承認済み":"差し戻し";d.Histories.Add(new History{ApplicationId=id,ActorId=u.Id,Action=a.Status,Comment=x.Comment,At=DateTime.UtcNow});d.SaveChanges();Mail(a.Applicant!.Email,$"【{(x.Action=="approve"?"承認完了":"差し戻し")}】{a.Title}",$"申請番号: {a.Number}\nステータス: {a.Status}\n申請詳細URL: /applications/{id}");return Results.Ok(new{message=x.Action=="approve"?"承認しました":"差し戻しました"});}if(x.Action=="cancel"&&a.ApplicantId==u.Id&&a.Status!="承認済み"&&a.Status!="取消"){a.Status="取消";d.Histories.Add(new History{ApplicationId=id,ActorId=u.Id,Action="取り消し",Comment=x.Comment,At=DateTime.UtcNow});d.SaveChanges();return Results.Ok(new{message="申請を取り消しました"});}return Results.BadRequest(new{message="現在のステータスではこの操作は実行できません"});});
app.MapGet("/api/dashboard",(HttpContext c,AppDb d)=>{var u=Cur(c,d);if(u==null)return Results.Unauthorized();var mine=d.Applications.Where(a=>a.ApplicantId==u.Id);return Results.Ok(new{counts=mine.GroupBy(a=>a.Status).ToDictionary(g=>g.Key,g=>g.Count()),recent=mine.OrderByDescending(a=>a.ApplicationDate).Take(5).Select(a=>new{a.Id,a.Number,a.Title,a.Status}),pending=u.Role=="一般"?0:d.Applications.Count(a=>a.ApproverId==u.Id&&a.Status=="承認待ち"),users=Admin(u)?d.Users.Count():0,total=Admin(u)?d.Applications.Count():0});});
app.MapGet("/api/settings",(HttpContext c,AppDb d)=>{var u=Cur(c,d);return !Admin(u)?Results.Json(new{message="システム設定の権限がありません"},statusCode:403):Results.Ok(d.Settings.First());}); app.MapPost("/api/settings/test",(HttpContext c,AppDb d)=>{var u=Cur(c,d);if(!Admin(u))return Results.Json(new{message="システム設定の権限がありません"},statusCode:403);Mail(d.Settings.First().From,"SMTPテスト送信","SMTPテスト送信に成功しました。");return Results.Ok(new{message="テスト送信に成功しました"});});
app.Run();
static void Seed(AppDb d){foreach(var x in new[]{new[]{"admin@example.com","管理者 太郎","管理部","管理者"},new[]{"kacho@example.com","課長 一郎","営業部","課長"},new[]{"bucho@example.com","部長 次郎","営業部","部長"},new[]{"ippan@example.com","一般 三郎","営業部","一般"}})d.Users.Add(new User{Email=x[0],Name=x[1],Department=x[2],Role=x[3],PasswordHash=BCrypt.Net.BCrypt.HashPassword("Password1"),Active=true});d.Settings.Add(new Setting{Host="localhost",Port=25,Username="smtp",From="admin@example.com",LockThreshold=5,Timeout=480});d.SaveChanges();}
record Login(string Email,string Password);record Register(string Name,string Email,string Password,string Confirm,string Department,string Role);record AppInput(string Type,string? Title,int Amount,string? Reason,DateTime ApplicationDate,bool Submit=false);record ActionInput(string Action,string? Comment); class AppDb:DbContext{public AppDb(DbContextOptions<AppDb> o):base(o){}public DbSet<User> Users=>Set<User>();public DbSet<Application> Applications=>Set<Application>();public DbSet<History> Histories=>Set<History>();public DbSet<Setting> Settings=>Set<Setting>();} class User{public int Id{get;set;}public string Name{get;set;}="";public string Email{get;set;}="";public string Department{get;set;}="";public string Role{get;set;}="一般";public string PasswordHash{get;set;}="";public bool Active{get;set;}public bool Locked{get;set;}public int Failures{get;set;}} class Application{public int Id{get;set;}public string? Number{get;set;}public string Type{get;set;}="";public string Title{get;set;}="";public int Amount{get;set;}public string Reason{get;set;}="";public DateTime ApplicationDate{get;set;}public string Status{get;set;}="下書き";public int ApplicantId{get;set;}public User? Applicant{get;set;}public int? ApproverId{get;set;}public User? Approver{get;set;}public List<History> History{get;set;}=new();} class History{public int Id{get;set;}public int ApplicationId{get;set;}public int ActorId{get;set;}public User? Actor{get;set;}public string Action{get;set;}="";public string? Comment{get;set;}public DateTime At{get;set;}} class Setting{public int Id{get;set;}public string Host{get;set;}="";public int Port{get;set;}public string Username{get;set;}="";public string From{get;set;}="";public int LockThreshold{get;set;}public int Timeout{get;set;}}

